import{_ as o,H as t,f as a,i as r}from"./chunks/framework.BauLNg70.js";const u=JSON.parse('{"title":"Featured mods","description":"","frontmatter":{},"headers":[],"relativePath":"featured.md","filePath":"featured.md"}'),i={name:"featured.md"};function s(n,e,d,m,h,l){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="featured-mods" tabindex="-1">Featured mods <a class="header-anchor" href="#featured-mods" aria-label="Permalink to &quot;Featured mods&quot;">​</a></h1><p>Selection curated by the studio. No algorithms: a team member picks, and the list lives in <a href="https://github.com/leteoworks/mod-portal-snake-classic/blob/main/featured.json" target="_blank" rel="noreferrer"><code>featured.json</code></a> in the portal repo. Choices are documented in <a href="https://github.com/leteoworks/my-game-fw/blob/main/docs/mods/operations/featured-mods-curation.md" target="_blank" rel="noreferrer"><code>operations/featured-mods-curation.md</code></a> in the framework repo.</p><blockquote><p><strong>This is not a partnership or paid system</strong>. Appearing here doesn&#39;t imply a commercial agreement — it&#39;s free recognition for the modder&#39;s work. If the verification tier (<code>workshopVerified</code>) is activated in the future, featured mods may pass to the verified tier with a separate process.</p></blockquote><hr><h2 id="mod-of-the-month" tabindex="-1">Mod of the month <a class="header-anchor" href="#mod-of-the-month" aria-label="Permalink to &quot;Mod of the month&quot;">​</a></h2><p><em>No nominee for this month. Know a mod that deserves the spotlight? Open it on <a href="https://steamcommunity.com/app/TBD/workshop/" target="_blank" rel="noreferrer">Workshop Discussions</a> with the &quot;Featured nomination&quot; tag.</em></p><hr><h2 id="current-selection" tabindex="-1">Current selection <a class="header-anchor" href="#current-selection" aria-label="Permalink to &quot;Current selection&quot;">​</a></h2><h3 id="fun-config-—-by-studio-leteo" tabindex="-1">Fun Config — by Studio Leteo <a class="header-anchor" href="#fun-config-—-by-studio-leteo" aria-label="Permalink to &quot;Fun Config — by Studio Leteo&quot;">​</a></h3><p><code>studio.fun-config</code> · <em>First Party · Customization</em></p><p>Official first-party mod. Customize power-ups, speed, and progression with fun presets. Serves as a living reference for modders just starting — its code lives in <a href="https://github.com/leteoworks/my-game-fw-mods/tree/main/snake-classic/studio.fun-config" target="_blank" rel="noreferrer"><code>game-mods/snake-classic/studio.fun-config/</code></a> of the first-party mods subrepo, open and clonable.</p><hr><h2 id="how-to-nominate-a-mod" tabindex="-1">How to nominate a mod? <a class="header-anchor" href="#how-to-nominate-a-mod" aria-label="Permalink to &quot;How to nominate a mod?&quot;">​</a></h2><ol><li>The mod must be published on Steam Workshop with visibility Public.</li><li>Open a thread on the game&#39;s Workshop Discussions with title <code>Featured nomination: &lt;modId&gt;</code>.</li><li>Include 2-3 sentences on why the mod deserves the spotlight.</li><li>The studio reviews nominations periodically (not instant — expect days/weeks).</li><li>If it makes it in, it appears here + on the portal home. The modder gets a ping on Workshop Discussions.</li></ol><h2 id="how-does-it-get-removed" tabindex="-1">How does it get removed? <a class="header-anchor" href="#how-does-it-get-removed" aria-label="Permalink to &quot;How does it get removed?&quot;">​</a></h2><p>Auto: curation <strong>resets every 6 months</strong> to avoid featured mods staying indefinitely. Very long-lived mods (e.g. Fun Config) re-appear after review.</p><p>Reactive: if the studio detects that a featured mod has become problematic (persistent bugs, author abandoned, malicious behavior discovered), it leaves featured immediately. Extreme case → operational kill-switch (see <a href="https://github.com/leteoworks/my-game-fw/blob/main/docs/mods/operations/kill-switch-runbook.md" target="_blank" rel="noreferrer"><code>kill-switch-runbook.md</code></a>).</p>',17)])])}const f=o(i,[["render",s]]);export{u as __pageData,f as default};
